//! Command line front-end for elfcat.

use std::path::Path;
use std::process::exit;

mod elf;
mod report;

const USAGE: &str = concat!(
    "Usage: elfcat <filename>\n",
    "Writes <filename>.html to CWD."
);

enum Command {
    /// Produce a report for the given path.
    Report(String),
    Usage,
    Version,
}

/// Decide what to do based on the arguments we were handed.
///
/// elfcat takes exactly one operand.  A lone `-h`/`--help` or `-v`/`--version`
/// is treated as a request for the corresponding blurb; anything else in a
/// single-argument invocation is a file name, even when it starts with a dash.
fn parse_args<I: Iterator<Item = String>>(mut args: I) -> Option<Command> {
    let first = args.next()?;

    if args.next().is_some() {
        return None;
    }

    Some(match first.as_str() {
        "-h" | "--help" => Command::Usage,
        "-v" | "--version" => Command::Version,
        _ => Command::Report(first),
    })
}

/// Name of the report for a given input path: the last path component with
/// `.html` glued onto the end.  The report always lands in the current
/// directory, never next to the input.
fn report_name(path: &str) -> String {
    let base = Path::new(path)
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.to_string());

    base + ".html"
}

fn main() {
    let command = match parse_args(std::env::args().skip(1)) {
        Some(command) => command,
        None => {
            println!("{}", USAGE);
            exit(1);
        }
    };

    let path = match command {
        Command::Usage => {
            println!("{}", USAGE);
            return;
        }
        Command::Version => {
            println!("{} {}", env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION"));
            return;
        }
        Command::Report(path) => path,
    };

    let contents = match std::fs::read(&path) {
        Ok(contents) => contents,
        Err(why) => {
            println!("Failed to read file {:?}: {}", path, why);
            exit(1);
        }
    };

    let elf = match elf::ParsedElf::from_bytes(&path, contents) {
        Ok(elf) => elf,
        Err(why) => {
            println!("Failed to parse ELF: {}", why);
            exit(1);
        }
    };

    let report = report::render(&elf);

    if let Err(why) = std::fs::write(report_name(&path), report) {
        println!("Failed to write report: {}", why);
        exit(1);
    }
}

