//! Symbolic names for the ELF constants elfcat knows how to label.
//!
//! Every lookup here is deliberately partial: values that are not in a table
//! fall back to a printed number.  The exact spelling of those fallbacks is
//! part of the report format, so each family keeps its own formatter.

pub const ELFCLASS32: u8 = 1;
pub const ELFCLASS64: u8 = 2;

pub const ELFDATA2LSB: u8 = 1;
pub const ELFDATA2MSB: u8 = 2;

pub const EHDR32_SIZE: usize = 52;
pub const EHDR64_SIZE: usize = 64;
pub const PHDR32_SIZE: usize = 32;
pub const PHDR64_SIZE: usize = 56;
pub const SHDR32_SIZE: usize = 40;
pub const SHDR64_SIZE: usize = 64;

pub const PT_INTERP: u32 = 3;
pub const PT_NOTE: u32 = 4;

pub const SHT_STRTAB: u32 = 3;
pub const SHT_NOBITS: u32 = 8;

pub const NT_GNU_BUILD_ID: u32 = 3;

pub fn class_to_string(class: u8) -> &'static str {
    match class {
        ELFCLASS32 => "32-bit",
        ELFCLASS64 => "64-bit",
        _ => "",
    }
}

pub fn data_to_string(data: u8) -> &'static str {
    match data {
        ELFDATA2LSB => "Little endian",
        ELFDATA2MSB => "Big endian",
        _ => "",
    }
}

pub fn abi_to_string(abi: u8) -> String {
    let name = match abi {
        0 => "SysV",
        1 => "HP-UX",
        2 => "NetBSD",
        3 => "Linux",
        4 => "Hurd",
        6 => "Solaris",
        7 => "AIX",
        8 => "IRIX",
        9 => "FreeBSD",
        10 => "Tru64",
        11 => "Modesto",
        12 => "OpenBSD",
        13 => "OpenVMS",
        255 => "Standalone",
        _ => return format!("Unknown: {}", abi),
    };

    name.to_string()
}

pub fn e_type_to_string(e_type: u16) -> String {
    let name = match e_type {
        0 => "None (NONE)",
        1 => "Relocatable object file (REL)",
        2 => "Executable file (EXEC)",
        3 => "Shared object file (DYN)",
        4 => "Core file (CORE)",
        0xfe00 | 0xfeff => "Environment-specific use",
        0xff00 | 0xffff => "Processor-specific use",
        _ => return format!("Unknown {}", e_type),
    };

    name.to_string()
}

pub fn e_machine_to_string(e_machine: u16) -> String {
    let name = match e_machine {
        0 => "None",
        1 => "AT&T WE 32100",
        2 => "SPARC",
        3 => "x86",
        4 => "Motorolla 68000",
        5 => "Motorolla 88000",
        6 => "Intel MCU",
        7 => "Intel 80860",
        8 => "MIPS",
        9 => "IBM System/370",
        10 => "MIPS RS3000 little-endian",
        14 => "HP PA-RISC",
        19 => "Intel 80960",
        20 => "PowerPC",
        21 => "PowerPC 64-bit",
        22 => "S390",
        40 => "ARM Aarch32",
        50 => "Itanium IA-64",
        62 => "x86-64",
        183 => "ARM Aarch64",
        190 => "CUDA",
        224 => "AMDGPU",
        243 => "RISC-V",
        _ => return format!("Unknown: {}", e_machine),
    };

    name.to_string()
}

pub fn p_flags_to_string(flags: u32) -> String {
    let mut s = String::new();

    if flags & 4 != 0 {
        s.push('R');
    }
    if flags & 2 != 0 {
        s.push('W');
    }
    if flags & 1 != 0 {
        s.push('X');
    }

    s
}

pub fn sh_flags_to_string(flags: u64) -> String {
    let mut s = String::new();

    if flags & 1 != 0 {
        s.push('W');
    }
    if flags & 2 != 0 {
        s.push('A');
    }
    if flags & 4 != 0 {
        s.push('X');
    }

    if s.is_empty() {
        s.push('0');
    }

    s
}

