//! Turning a blob of bytes into the pieces the report generator needs.
//!
//! The parser is deliberately forgiving: apart from a handful of sanity checks
//! on `e_ident` it accepts whatever it finds and reports it verbatim.  A broken
//! file is exactly the kind of thing you want to look at in a hex dump.

use super::defs::*;
use super::notes::{self, Note};

/// What a byte belongs to.  Doubles as the source of the CSS class names used
/// by the dump, hence the indices carried by the table entries.
#[derive(Clone, Copy)]
pub enum RangeKind {
    Ehdr,
    Ident,
    /// A named field of one of the header structs.
    Field(&'static str),
    Phdr(usize),
    Shdr(usize),
    Segment(usize),
    Section(usize),
    /// A note inside a `PT_NOTE` segment.
    SegmentSubrange,
}

impl RangeKind {
    /// The `class` attribute the dump emits for a span of this kind.
    pub fn class(&self) -> String {
        match *self {
            RangeKind::Ehdr => "ehdr".to_string(),
            RangeKind::Ident => "ident".to_string(),
            RangeKind::Field(name) => name.to_string(),
            RangeKind::Phdr(idx) => format!("bin_phdr{} phdr", idx),
            RangeKind::Shdr(idx) => format!("bin_shdr{} shdr", idx),
            RangeKind::Segment(idx) => format!("bin_segment{} segment", idx),
            RangeKind::Section(idx) => format!("bin_section{} section hover", idx),
            RangeKind::SegmentSubrange => "segment_subrange hover".to_string(),
        }
    }
}

/// Per-byte bookkeeping for the dump.
///
/// `opens[i]` lists the ranges that begin at byte `i`, in the order they were
/// registered; `closes[i]` merely counts how many ranges end *on* byte `i`.
/// The dump walks bytes in order, opens spans, and closes `closes[i]` of them
/// afterwards - which is why registration order is what decides nesting.
pub struct Ranges {
    pub opens: Vec<Vec<RangeKind>>,
    pub closes: Vec<usize>,
}

impl Ranges {
    fn new(len: usize) -> Ranges {
        Ranges {
            opens: vec![vec![]; len],
            closes: vec![0; len],
        }
    }

    pub fn add(&mut self, start: usize, len: usize, kind: RangeKind) {
        self.opens[start].push(kind);

        let last = start + len - 1;

        self.closes[last] += 1;
    }
}

pub struct ParsedPhdr {
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: usize,
    pub p_vaddr: u64,
    pub p_filesz: usize,
    pub p_memsz: u64,
    pub p_align: u64,
}

pub struct ParsedShdr {
    pub name: String,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: usize,
    pub sh_size: usize,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
}

pub struct ParsedElf {
    pub filename: String,
    pub contents: Vec<u8>,
    pub class: u8,
    pub data: u8,
    pub abi: u8,
    pub abi_ver: u8,
    pub e_type: u16,
    pub e_machine: u16,
    pub e_entry: u64,
    pub e_phoff: usize,
    pub e_shoff: usize,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
    pub phdrs: Vec<ParsedPhdr>,
    pub shdrs: Vec<ParsedShdr>,
    pub notes: Vec<Note>,
    pub ranges: Ranges,
}

/// Little helper for pulling integers out of the blob with the file's byte order.
#[derive(Clone, Copy)]
pub struct Reader<'a> {
    pub bytes: &'a [u8],
    pub big_endian: bool,
}

impl<'a> Reader<'a> {
    pub fn u8(&self, off: usize) -> u8 {
        self.bytes[off]
    }

    pub fn u16(&self, off: usize) -> u16 {
        let b = [self.bytes[off], self.bytes[off + 1]];

        if self.big_endian {
            u16::from_be_bytes(b)
        } else {
            u16::from_le_bytes(b)
        }
    }

    pub fn u32(&self, off: usize) -> u32 {
        let mut b = [0u8; 4];
        b.copy_from_slice(&self.bytes[off..off + 4]);

        if self.big_endian {
            u32::from_be_bytes(b)
        } else {
            u32::from_le_bytes(b)
        }
    }

    pub fn u64(&self, off: usize) -> u64 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&self.bytes[off..off + 8]);

        if self.big_endian {
            u64::from_be_bytes(b)
        } else {
            u64::from_le_bytes(b)
        }
    }
}

/// Offsets of the ehdr fields after `e_ident`, per class.
/// `(name, offset, size)`.
const EHDR_FIELDS_64: &[(&str, usize, usize)] = &[
    ("e_type", 16, 2),
    ("e_machine", 18, 2),
    ("e_version", 20, 4),
    ("e_entry", 24, 8),
    ("e_phoff", 32, 8),
    ("e_shoff", 40, 8),
    ("e_flags", 48, 4),
    ("e_ehsize", 52, 2),
    ("e_phentsize", 54, 2),
    ("e_phnum", 56, 2),
    ("e_shentsize", 58, 2),
    ("e_shnum", 60, 2),
    ("e_shstrndx", 62, 2),
];

const EHDR_FIELDS_32: &[(&str, usize, usize)] = &[
    ("e_type", 16, 2),
    ("e_machine", 18, 2),
    ("e_version", 20, 4),
    ("e_entry", 24, 4),
    ("e_phoff", 28, 4),
    ("e_shoff", 32, 4),
    ("e_flags", 36, 4),
    ("e_ehsize", 40, 2),
    ("e_phentsize", 42, 2),
    ("e_phnum", 44, 2),
    ("e_shentsize", 46, 2),
    ("e_shnum", 48, 2),
    ("e_shstrndx", 50, 2),
];

const PHDR_FIELDS_64: &[(&str, usize, usize)] = &[
    ("p_type", 0, 4),
    ("p_flags", 4, 4),
    ("p_offset", 8, 8),
    ("p_vaddr", 16, 8),
    ("p_paddr", 24, 8),
    ("p_filesz", 32, 8),
    ("p_memsz", 40, 8),
    ("p_align", 48, 8),
];

const PHDR_FIELDS_32: &[(&str, usize, usize)] = &[
    ("p_type", 0, 4),
    ("p_offset", 4, 4),
    ("p_vaddr", 8, 4),
    ("p_paddr", 12, 4),
    ("p_filesz", 16, 4),
    ("p_memsz", 20, 4),
    ("p_flags", 24, 4),
    ("p_align", 28, 4),
];

const SHDR_FIELDS_64: &[(&str, usize, usize)] = &[
    ("sh_name", 0, 4),
    ("sh_type", 4, 4),
    ("sh_flags", 8, 8),
    ("sh_addr", 16, 8),
    ("sh_offset", 24, 8),
    ("sh_size", 32, 8),
    ("sh_link", 40, 4),
    ("sh_info", 44, 4),
    ("sh_addralign", 48, 8),
    ("sh_entsize", 56, 8),
];

const SHDR_FIELDS_32: &[(&str, usize, usize)] = &[
    ("sh_name", 0, 4),
    ("sh_type", 4, 4),
    ("sh_flags", 8, 4),
    ("sh_addr", 12, 4),
    ("sh_offset", 16, 4),
    ("sh_size", 20, 4),
    ("sh_link", 24, 4),
    ("sh_info", 28, 4),
    ("sh_addralign", 32, 4),
    ("sh_entsize", 36, 4),
];

impl ParsedElf {
    pub fn from_bytes(filename: &str, contents: Vec<u8>) -> Result<ParsedElf, String> {
        if contents.len() < 16 {
            return Err(String::from("file is smaller than ELF header's e_ident"));
        }

        if contents[0..4] != [0x7f, b'E', b'L', b'F'] {
            return Err(String::from("mismatched magic: not an ELF file"));
        }

        let class = contents[4];
        if class != ELFCLASS32 && class != ELFCLASS64 {
            return Err(format!("Unknown bitness: {}", class));
        }

        let data = contents[5];
        if data != ELFDATA2LSB && data != ELFDATA2MSB {
            return Err(format!("Unknown endianness: {}", data));
        }

        let wide = class == ELFCLASS64;
        let ehdr_size = if wide { EHDR64_SIZE } else { EHDR32_SIZE };

        if contents.len() < ehdr_size {
            return Err(String::from("file is smaller than ELF file header"));
        }

        let mut elf = ParsedElf {
            filename: filename.to_string(),
            class,
            data,
            abi: contents[7],
            abi_ver: contents[8],
            e_type: 0,
            e_machine: 0,
            e_entry: 0,
            e_phoff: 0,
            e_shoff: 0,
            e_flags: 0,
            e_ehsize: 0,
            e_phentsize: 0,
            e_phnum: 0,
            e_shentsize: 0,
            e_shnum: 0,
            e_shstrndx: 0,
            phdrs: vec![],
            shdrs: vec![],
            notes: vec![],
            ranges: Ranges::new(contents.len()),
            contents,
        };

        elf.read_ehdr();
        elf.add_ehdr_ranges();
        elf.parse_phdrs();
        elf.parse_shdrs();
        elf.collect_notes();

        Ok(elf)
    }

    fn reader(&self) -> Reader<'_> {
        Reader {
            bytes: &self.contents,
            big_endian: self.data == ELFDATA2MSB,
        }
    }

    fn wide(&self) -> bool {
        self.class == ELFCLASS64
    }

    fn read_ehdr(&mut self) {
        let r = self.reader();
        let wide = self.wide();

        self.e_type = r.u16(16);
        self.e_machine = r.u16(18);

        if wide {
            self.e_entry = r.u64(24);
            self.e_phoff = r.u64(32) as usize;
            self.e_shoff = r.u64(40) as usize;
            self.e_flags = r.u32(48);
            self.e_ehsize = r.u16(52);
            self.e_phentsize = r.u16(54);
            self.e_phnum = r.u16(56);
            self.e_shentsize = r.u16(58);
            self.e_shnum = r.u16(60);
            self.e_shstrndx = r.u16(62);
        } else {
            self.e_entry = r.u32(24) as u64;
            self.e_phoff = r.u32(28) as usize;
            self.e_shoff = r.u32(32) as usize;
            self.e_flags = r.u32(36);
            self.e_ehsize = r.u16(40);
            self.e_phentsize = r.u16(42);
            self.e_phnum = r.u16(44);
            self.e_shentsize = r.u16(46);
            self.e_shnum = r.u16(48);
            self.e_shstrndx = r.u16(50);
        }
    }

    fn add_ehdr_ranges(&mut self) {
        let ehsize = self.e_ehsize as usize;

        self.ranges.add(0, ehsize, RangeKind::Ehdr);
        self.ranges.add(0, 16, RangeKind::Ident);

        for (name, start, len) in [
            ("magic", 0, 4),
            ("class", 4, 1),
            ("data", 5, 1),
            ("ver", 6, 1),
            ("abi", 7, 1),
            ("abi_ver", 8, 1),
            ("pad", 9, 7),
        ] {
            self.ranges.add(start, len, RangeKind::Field(name));
        }

        let fields = if self.wide() {
            EHDR_FIELDS_64
        } else {
            EHDR_FIELDS_32
        };

        for &(name, start, len) in fields {
            self.ranges.add(start, len, RangeKind::Field(name));
        }
    }

    fn parse_phdrs(&mut self) {
        let entsize = if self.wide() { PHDR64_SIZE } else { PHDR32_SIZE };
        let fields = if self.wide() {
            PHDR_FIELDS_64
        } else {
            PHDR_FIELDS_32
        };

        for idx in 0..self.e_phnum as usize {
            let base = self.e_phoff + idx * entsize;
            let phdr = self.read_phdr(base);

            if phdr.p_filesz != 0 {
                self.ranges
                    .add(phdr.p_offset, phdr.p_filesz, RangeKind::Segment(idx));
            }

            self.ranges.add(base, entsize, RangeKind::Phdr(idx));

            for &(name, off, len) in fields {
                self.ranges.add(base + off, len, RangeKind::Field(name));
            }

            self.phdrs.push(phdr);
        }
    }

    fn read_phdr(&self, base: usize) -> ParsedPhdr {
        let r = self.reader();

        if self.wide() {
            ParsedPhdr {
                p_type: r.u32(base),
                p_flags: r.u32(base + 4),
                p_offset: r.u64(base + 8) as usize,
                p_vaddr: r.u64(base + 16),
                p_filesz: r.u64(base + 32) as usize,
                p_memsz: r.u64(base + 40),
                p_align: r.u64(base + 48),
            }
        } else {
            ParsedPhdr {
                p_type: r.u32(base),
                p_offset: r.u32(base + 4) as usize,
                p_vaddr: r.u32(base + 8) as u64,
                p_filesz: r.u32(base + 16) as usize,
                p_memsz: r.u32(base + 20) as u64,
                p_flags: r.u32(base + 24),
                p_align: r.u32(base + 28) as u64,
            }
        }
    }

    fn parse_shdrs(&mut self) {
        let entsize = if self.wide() { SHDR64_SIZE } else { SHDR32_SIZE };
        let fields = if self.wide() {
            SHDR_FIELDS_64
        } else {
            SHDR_FIELDS_32
        };

        let strtab = self.shstrtab_offset();

        for idx in 0..self.e_shnum as usize {
            let base = self.e_shoff + idx * entsize;
            let shdr = self.read_shdr(base, strtab);

            if shdr.sh_size != 0 && shdr.sh_type != SHT_NOBITS {
                self.ranges
                    .add(shdr.sh_offset, shdr.sh_size, RangeKind::Section(idx));
            }

            self.ranges.add(base, entsize, RangeKind::Shdr(idx));

            for &(name, off, len) in fields {
                self.ranges.add(base + off, len, RangeKind::Field(name));
            }

            self.shdrs.push(shdr);
        }
    }

    /// File offset of the section-name string table, if we can find one.
    fn shstrtab_offset(&self) -> Option<usize> {
        let entsize = if self.wide() { SHDR64_SIZE } else { SHDR32_SIZE };
        let idx = self.e_shstrndx as usize;

        if idx >= self.e_shnum as usize {
            return None;
        }

        let base = self.e_shoff + idx * entsize;
        let r = self.reader();

        Some(if self.wide() {
            r.u64(base + 24) as usize
        } else {
            r.u32(base + 16) as usize
        })
    }

    fn read_shdr(&self, base: usize, strtab: Option<usize>) -> ParsedShdr {
        let r = self.reader();

        let (name_off, mut shdr) = if self.wide() {
            (
                r.u32(base),
                ParsedShdr {
                    name: String::new(),
                    sh_type: r.u32(base + 4),
                    sh_flags: r.u64(base + 8),
                    sh_addr: r.u64(base + 16),
                    sh_offset: r.u64(base + 24) as usize,
                    sh_size: r.u64(base + 32) as usize,
                    sh_link: r.u32(base + 40),
                    sh_info: r.u32(base + 44),
                    sh_addralign: r.u64(base + 48),
                    sh_entsize: r.u64(base + 56),
                },
            )
        } else {
            (
                r.u32(base),
                ParsedShdr {
                    name: String::new(),
                    sh_type: r.u32(base + 4),
                    sh_flags: r.u32(base + 8) as u64,
                    sh_addr: r.u32(base + 12) as u64,
                    sh_offset: r.u32(base + 16) as usize,
                    sh_size: r.u32(base + 20) as usize,
                    sh_link: r.u32(base + 24),
                    sh_info: r.u32(base + 28),
                    sh_addralign: r.u32(base + 32) as u64,
                    sh_entsize: r.u32(base + 36) as u64,
                },
            )
        };

        if let Some(strtab) = strtab {
            shdr.name = self.string_at(strtab + name_off as usize);
        }

        shdr
    }

    /// NUL-terminated string starting at a file offset, clipped at EOF.
    pub fn string_at(&self, start: usize) -> String {
        if start >= self.contents.len() {
            return String::new();
        }

        let tail = &self.contents[start..];
        let len = tail.iter().position(|&b| b == 0).unwrap_or(tail.len());

        String::from_utf8_lossy(&tail[..len]).into_owned()
    }

    fn collect_notes(&mut self) {
        let mut notes = vec![];
        let mut subranges = vec![];

        for phdr in &self.phdrs {
            if phdr.p_type != PT_NOTE {
                continue;
            }

            notes::parse(
                &self.contents,
                self.data == ELFDATA2MSB,
                phdr.p_offset,
                phdr.p_filesz,
                &mut notes,
                &mut subranges,
            );
        }

        for (start, len) in subranges {
            self.ranges.add(start, len, RangeKind::SegmentSubrange);
        }

        self.notes = notes;
    }

    /// Contents of the segment described by `phdr`, clipped at EOF.
    pub fn segment_bytes(&self, phdr: &ParsedPhdr) -> &[u8] {
        let start = phdr.p_offset.min(self.contents.len());
        let end = start.saturating_add(phdr.p_filesz).min(self.contents.len());

        &self.contents[start..end]
    }

    /// Contents of the section described by `shdr`, clipped at EOF.
    pub fn section_bytes(&self, shdr: &ParsedShdr) -> &[u8] {
        let start = shdr.sh_offset.min(self.contents.len());
        let end = start.saturating_add(shdr.sh_size).min(self.contents.len());

        &self.contents[start..end]
    }
}

