/// Per-byte bookkeeping for the dump.
///
/// `opens[i]` lists the ranges that begin at byte `i`, in the order they were
/// registered; `closes[i]` merely counts how many ranges end *on* byte `i`.
/// The dump walks bytes in order, opens spans, and closes `closes[i]` of them
/// afterwards - which is why registration order is what decides nesting.
pub struct Ranges {
    pub opens: Vec<Vec<RangeKind>>,
    pub closes: Vec<usize>,
}

impl Ranges {
    fn new(len: usize) -> Ranges {
        Ranges {
            opens: vec![vec![]; len],
            closes: vec![0; len],
        }
    }

    pub fn add(&mut self, start: usize, len: usize, kind: RangeKind) {
        self.opens[start].push(kind);

        let last = start + len - 1;

        self.closes[last] += 1;
    }
}

