/// Per-byte bookkeeping for the dump.
///
/// `data[i]` lists the ranges that begin at byte `i`, in the order they were
/// registered; `ends[i]` merely counts how many ranges finish *on* byte `i`.
/// The dump walks bytes in order, opens spans, and closes `ends[i]` of them
/// afterwards - which is why registration order is what decides nesting.
pub struct Ranges {
    pub data: Vec<Vec<RangeKind>>,
    pub ends: Vec<usize>,
}

impl Ranges {
    fn new(len: usize) -> Ranges {
        Ranges {
            data: vec![vec![]; len],
            ends: vec![0; len],
        }
    }

    pub fn add(&mut self, start: usize, len: usize, kind: RangeKind) {
        self.data[start].push(kind);
        self.ends[start + len - 1] += 1;
    }
}

