//! Small formatting helpers shared by every part of the report.

/// Escape the characters that would otherwise be markup.
pub fn escape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());

    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }

    out
}

const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];

/// Split a byte count into a mantissa and a binary unit.  Anything below a
/// kibibyte stays unscaled, which is how callers detect "no unit needed".
fn scale(bytes: u64) -> (f64, &'static str) {
    let mut value = bytes as f64;
    let mut unit = 0;

    while value >= 1024.0 && unit + 1 < UNITS.len() {
        value /= 1024.0;
        unit += 1;
    }

    (value, UNITS[unit])
}

/// How the file size is spelled in the summary table: human form first.
pub fn file_size(bytes: u64) -> String {
    if bytes < 1024 {
        return format!("{} B", bytes);
    }

    let (value, unit) = scale(bytes);

    format!("{:.1} {} ({} B)", value, unit, bytes)
}

/// How sizes are spelled inside the info tables: exact count first, with the
/// human form in parentheses once it is worth having.
pub fn size(bytes: u64) -> String {
    if bytes < 1024 {
        return format!("{}", bytes);
    }

    let (value, unit) = scale(bytes);

    format!("{} ({:.1} {})", bytes, value, unit)
}

/// A number shown in hex, with the decimal value in the tooltip.
pub fn hex_number(value: u64) -> String {
    format!("<span class='number' title='{}'>{:#x}</span>", value, value)
}

/// A size shown in decimal, with the hex value in the tooltip.
pub fn size_number(value: u64) -> String {
    format!(
        "<span class='number' title='{:#x}'>{}</span>",
        value,
        size(value)
    )
}

