//! The three side-by-side columns: offsets, hex dump, printable ASCII.

use crate::elf::{ParsedElf, Ranges};

const COLUMNS: usize = 16;

/// Left column: the file offset of every dump row, in bare lowercase hex.
pub fn offsets(len: usize) -> String {
    let mut out = String::new();

    for i in 0..len {
        if i % COLUMNS == 0 {
            out.push_str(&format!("{:x}", i));
        }

        if i % COLUMNS == COLUMNS - 1 {
            out.push('\n');
        }
    }

    out
}

/// Middle column: the hex dump, wrapped in the spans that colour it.
///
/// Spans are opened and closed purely by position, and closing is done by
/// count.  Overlapping ranges therefore produce tags that nest differently
/// than the ranges do; the CSS is written with that in mind.
pub fn bytes(elf: &ParsedElf) -> String {
    let mut out = String::new();
    let ranges: &Ranges = &elf.ranges;

    for (i, &byte) in elf.contents.iter().enumerate() {
        if i != 0 {
            out.push(if i % COLUMNS == 0 { '\n' } else { ' ' });
        }

        for kind in &ranges.data[i] {
            out.push_str(&format!("<span class='{}'>", kind.class()));
        }

        // Inside the magic the interesting thing is the "ELF" text, so show
        // the characters instead of their codes.  A leading no-break space
        // keeps the columns aligned with the hex ones.
        if i < 4 && byte.is_ascii_graphic() {
            out.push_str("&nbsp;");
            out.push(byte as char);
        } else {
            out.push_str(&format!("{:02x}", byte));
        }

        for _ in 0..ranges.ends[i] {
            out.push_str("</span>");
        }
    }

    out
}

/// Right column: printable characters, everything else as a dot.
pub fn ascii(contents: &[u8]) -> String {
    let mut out = String::new();

    for (i, &byte) in contents.iter().enumerate() {
        match byte {
            b'&' => out.push_str("&amp;"),
            b'<' => out.push_str("&lt;"),
            b'>' => out.push_str("&gt;"),
            b'"' => out.push_str("&quot;"),
            b'\'' => out.push_str("&apos;"),
            _ if byte.is_ascii_graphic() => out.push(byte as char),
            _ => out.push('.'),
        }

        if i % COLUMNS == COLUMNS - 1 {
            out.push('\n');
        }
    }

    out
}

